+            """, filter);
+
+        request.setJsonEntity(Strings.format("""
+            {
+              "knn": {
+                  "field": "%s",
+                  "k": 5,
+                  "num_candidates": 10,
+                  "filter": %s,
+                  "query_vector_builder": {
+                    "text_embedding": {
+                      "model_id": "%s",
+                      "model_text": "%s"
